const LECTURE_SRC_PREFIX = '강의:';

/* ===================== 공용 유틸 ===================== */

function ensureSheet(ss, name, headers) {
  let sh = ss.getSheetByName(name);
  if (!sh) {
    sh = ss.insertSheet(name);
    sh.getRange(1, 1, 1, headers.length).setValues([headers]);
    sh.setFrozenRows(1);
  }
  return sh;
}

function writeIfChanged(sheet, row, col, values) {
  if (!values.length) return false;
  const rng = sheet.getRange(row, col, values.length, values[0].length);
  if (JSON.stringify(rng.getValues()) === JSON.stringify(values)) return false;
  // [v9.153] 문자열 셀은 셀안전_(상담AI.js·런타임 호출=로드 순서 무관)로 소독해 쓴다 — 이 통로로 상담시트 원문(남의 글)이
  //   profiles에 실리므로 `=` 시작 문자열이 라이브 수식이 되는 것을 채널에서 차단. Date·number는 제외(String 강제=타입 파괴).
  //   비교는 소독 전 원문: 아포스트로피 접두는 저장 시 소비돼 getValues가 원문을 돌려주므로,
  //   소독본으로 비교하면 그 블록이 매 실행 「다름」이 되어 [v9.25] 무변경 skip이 죽는다.
  rng.setValues(행소독_(values));
  return true;
}

/* [v9.157] 시트 직기입 소독 통로 — 폼·외부 유래 행을 setValues/appendRow 하기 전에 반드시 통과시킨다.
 *   writeIfChanged를 타는 경로는 채널에서 이미 소독되므로(위) 이건 그 밖의 직기입 전용:
 *   폼 스위프(리드·강의·마감·상담)처럼 「남의 글」을 append하는 자리가 원래 방어의 사각이었다.
 *   문자열만 셀안전_로, Date·number는 타입 보존 — String 강제는 날짜·수량 칸을 죽인다.
 *   2차원(행 배열)·1차원(한 행) 둘 다 받는다. 호출부마다 map 람다를 새로 쓰지 않는 것이 요점이다
 *   — 같은 방어를 N번째 손으로 얹는 순간 N+1번째가 빠진다(v9.153 계열 재발 7건의 실측 교훈). */
function 행소독_(rows) {
  const cell = (v) => (typeof v === 'string' ? 셀안전_(v) : v);
  return rows.map((r) => (Array.isArray(r) ? r.map(cell) : cell(r)));
}

function dstr(v, tz, fmt) { // 날짜값 안전 문자열화
  if (!v) return '';
  if (v instanceof Date) return Utilities.formatDate(v, tz, fmt || 'yyyy-MM-dd');
  return String(v).substring(0, (fmt === 'yyyy-MM') ? 7 : 10);
}

/* [v9.181] 「미정」 판정 단일 소스 — 선택지에 정직한 「아직 모르겠다」를 만들면 **그 값을 읽는 곳 전부**가
 * 그것을 값이 아니라 **상태**로 다뤄야 한다. 안 그러면 정직하게 미정을 고른 사람이 가장 이상한 결과를 받는다:
 *   · 여정 카드 → 「🎯 TOPIK 아직 미정까지 약 48주」   · 핵심비전 → 「자기신고: … · TOPIK 아직 미정」
 *   · 궤적 판정 → 유학 의도가 있는 것으로 세어 「불일치(유학→취업)」 (없는 의도로 내린 판정)
 * 읽는 곳이 넷이라 프로즈로 「미정은 걸러라」라고 적는 대신 통로를 하나 둔다(N번째가 빠지는 것을 막는다).
 * ⚠ 여기서 true 라고 「값을 버리라」는 뜻이 아니다 — 원본은 상담시트·trajectory 에 그대로 남는다.
 *   버리는 것은 **그 값으로 문장을 만들거나 의도를 추정하는 것**뿐이다. */
function 미정값_(v) { return !v || /미정|모름|모르|정하지/.test(String(v)); }

function toDate_(v) { // [v9.22] Date/yyyymmdd(문자·숫자) → Date, 실패 시 null
  if (v instanceof Date) return v;
  const s = String(v == null ? '' : v).replace(/\D/g, '');
  if (s.length === 8) { const d = new Date(Number(s.slice(0, 4)), Number(s.slice(4, 6)) - 1, Number(s.slice(6, 8))); return isNaN(d.getTime()) ? null : d; }
  return null;
}

// [opt] 셀값(Date 또는 문자/숫자) → Date 관용 강제. toDate_와 별개: 실패 시 null이 아니라 원 동작(new Date) 유지. 20곳 중복 일원화.
function asDate_(d) { return d instanceof Date ? d : new Date(d); }

// [v9.34] 'yyyy-MM' 월키 산술 — new Date(y,m-1,1)(스크립트TZ 자정)+formatDate(시트TZ) 혼용 시 시트TZ가 서쪽이면
//   월키가 한 달 밀려 배치가 통째 스킵되던 결함의 단일 해법. TZ 무관 순수 문자열 연산.
function ymShift_(ym, delta) {
  const y = Number(String(ym).slice(0, 4)), m0 = Number(String(ym).slice(5, 7)) - 1 + delta;
  const yy = y + Math.floor(m0 / 12), mm = ((m0 % 12) + 12) % 12;
  return yy + '-' + ('0' + (mm + 1)).slice(-2);
}

// [v9.34] 생일값(Date·yyyymmdd·yyyy-MM-dd) → 'MM-dd'. String slice 원시 판정이 Date 셀에서 전멸하던 것 통일(6017 패턴)
function bdayMMDD_(v, tz) { const d = toDate_(v); return d ? Utilities.formatDate(d, tz, 'MM-dd') : ''; }

function getState(st, key) {
  const last = st.getLastRow();
  if (last < 1) return { row: -1, val: '' };
  const data = st.getRange(1, 1, last, 2).getValues();
  for (let i = 0; i < data.length; i++) {
    if (String(data[i][0]) === key) return { row: i + 1, val: data[i][1] };
  }
  return { row: -1, val: '' };
}
function setState(st, key, val) {
  const g = getState(st, key);
  if (g.row > 0) {
    if (String(g.val) !== String(val)) st.getRange(g.row, 2).setValue(val);
  } else {
    st.getRange(st.getLastRow() + 1, 1, 1, 2).setValues([[key, val]]);
  }
}

/* --- PL 채번: app_state 카운터 + Lock (아카이빙 후에도 중복 없음) --- */
function reservePlIds(ss, count) {
  const lock = LockService.getScriptLock();
  lock.waitLock(30000);
  try {
    const st = ensureSheet(ss, 'app_state', ['key', 'value']);
    let g = getState(st, 'PL카운터');
    let cur = Number(g.val) || 0;
    if (cur === 0) { // 최초 1회: 현재+아카이브 최대값으로 초기화
      ['point_logs', 'point_logs_archive'].forEach(name => {
        const sh = ss.getSheetByName(name);
        if (!sh || sh.getLastRow() < 2) return;
        sh.getRange(2, 1, sh.getLastRow() - 1, 1).getValues().forEach(r => {
          const m = String(r[0]).match(/^PL(\d+)$/);
          if (m) cur = Math.max(cur, parseInt(m[1], 10));
        });
      });
    }
    const ids = [];
    // [v5] slice(-3) → padStart: 1000건 이후 ID 중복 버그 수정
    for (let i = 1; i <= count; i++) ids.push('PL' + String(cur + i).padStart(3, '0'));
    setState(st, 'PL카운터', cur + count);
    return ids;
  } finally { lock.releaseLock(); }
}

/* --- point_logs 추가는 전부 이 함수로 (동시성 안전) --- */
function appendPoints(ss, rows) { // rows: [[sid, pts, reason, by], ...]
  if (!rows.length) return;
  const lock = LockService.getScriptLock();
  lock.waitLock(30000);
  try {
    const pl = ss.getSheetByName('point_logs');
    const ids = reservePlIdsInner(ss, rows.length);
    const now = new Date();
    const out = rows.map((r, i) => [ids[i], r[0], r[1], r[2], r[3], now]);
    pl.getRange(pl.getLastRow() + 1, 1, out.length, 6).setValues(out);
  } finally { lock.releaseLock(); }
}
// appendPoints 내부용 (이미 lock 보유 상태)
function reservePlIdsInner(ss, count) {
  const st = ensureSheet(ss, 'app_state', ['key', 'value']);
  let g = getState(st, 'PL카운터');
  let cur = Number(g.val) || 0;
  if (cur === 0) {
    ['point_logs', 'point_logs_archive'].forEach(name => {
      const sh = ss.getSheetByName(name);
      if (!sh || sh.getLastRow() < 2) return;
      sh.getRange(2, 1, sh.getLastRow() - 1, 1).getValues().forEach(r => {
        const m = String(r[0]).match(/^PL(\d+)$/);
        if (m) cur = Math.max(cur, parseInt(m[1], 10));
      });
    });
  }
  const ids = [];
  // [v5] slice(-3) → padStart: 1000건 이후 ID 중복 버그 수정
  for (let i = 1; i <= count; i++) ids.push('PL' + String(cur + i).padStart(3, '0'));
  setState(st, 'PL카운터', cur + count);
  return ids;
}

/* --- 시간표 --- */
/* ===================== [v9.95→v9.102] 반 편성 정본 — 4실 24반 · 전 반 정원 16명 =====================
 * 원천: 급여 인센티브 정본 v1.1 §1(16석 균일) + 유호님 2026-08-01 확정.
 * [v9.102] **3실 폐기 · 4실 확정**(유호 08-01) — 개원 기본값이 3실 18반 → 4실 24반 384석이 됐다.
 *   실 구성 = 25평 1실 + 13평 3실 + 사무실 11평 + 상담실 2평. 급여 정본 v1.1의 임대 200㎡·몽골쌤 6명·
 *   BEP 117명은 이 확정으로 **전부 무효**다(재산정은 유호님 소관 — 코드는 반 구성만 따라간다).
 *   ⚠ 25평 실과 13평 실의 정원을 같은 16으로 두면 25평이 논다. 방별 정원은 schedule D열로 조정 가능하다
 *     — 정원을 이름에서 데이터로 뺀 v9.95 결정의 배당금이라 코드 수정이 필요 없다.
 *
 * 무엇이 바뀌었나 — **정원을 이름에서 데이터로 옮겼다.**
 *   구 v8.3은 반 이름으로 정원을 판정했다('집중반' 포함=10 · 정규반1~4=20 · 주말정규반=20).
 *   이름이 곧 설정이라 ①정원을 바꾸려면 이름 체계부터 갈아야 했고 ②이름을 예쁘게 지으면 정원이 깨졌다.
 *   전 반 16명 균일이 되면서 그 분기는 정보량이 0이 됐으므로, 정원을 schedule 시트 D열로 뺀다.
 *   → 이름은 좌표일 뿐이고 정원·표시명은 데이터다. 유호님이 코드 없이 시트에서 바꾼다.
 *
 * 이름 3층 분리(유호 08-01 확정) — 한 문자열에 키와 브랜드를 같이 넣지 않는다.
 *   키의 조건(안 바뀔 것·고유할 것·시각을 알려줄 것)과 이름의 조건(부르고 싶을 것)은 상충한다:
 *   ① 키 (A열 '반')    = `평일11A` — 코드·상담시트 입력값. 영원히 안 바뀐다. 6자 고정.
 *   ② 문패 (코드 밖)   = 몽골 별자리(알탄가다스·구르왕마랄·훈타왕어드·놈솜) — 강의실 벽이라 길어도 된다.
 *   ③ 표시명 (E열)     = 학생·학부모가 보는 이름. 개원엔 시각('11시 A'), 시즌 1 이후 각 반이 직접 짓는다.
 *      → setupSchedule 재실행이 ③을 덮어쓰지 않는다(아래 prev 보존). 되돌릴 수 없는 사고를 기계로 막는다.
 *
 * 15:30반의 태그가 '15'인 이유: 코어 슬롯이 11·14·15:30·18 넷뿐이라 분을 떼도 서로 안 겹친다.
 *   수업 시각의 단일 소스는 C열 '시작시간'(15:30)이다 — 이름은 라벨일 뿐 코드가 시각으로 읽지 않는다.
 *
 * 단계 개방은 인자 하나로 한다 — 급여 정본 §4의 램프업이 그대로 살아 있다:
 *   setupSchedule(2)=12반 192석 · (3)=18반 288석 · 생략=**(4)=24반 384석(확정 기준선)**.
 *   개원 초 좌석이 남으면 작은 수로 열고, 채워지면 재실행한다(표시명은 보존되므로 이름이 안 날아간다).
 */
const SCHEDULE_HEADERS = ['반', '요일유형', '시작시간', '정원', '표시명'];
const CLASS_CAP_DEFAULT = 16;  // 급여 정본 v1.1 §1 — 전 반 동일 정원. 시트 D열이 비었거나 구 3열 시트면 이 값으로 폴백
const CORE_ROOMS_DEFAULT = 4;  // [v9.102] 유호 08-01 확정 — 3실 폐기·4실 24반 384석이 기준선(구 3실 18반은 setupSchedule(3))
const ROOM_LETTERS = ['A', 'B', 'C', 'D']; // 강의실 문패와 1:1(1실=A … 4실=D) — 학생이 반 이름만 보고 어느 문인지 안다
const CORE_SLOTS = [ // 코어 = 출석·스트릭·레이드 대상. 위성(댄스·뷰티·보컬·원어민 회화·글로벌 영어)은 출석 없음 → 미등록
  { type: '평일', tag: '11', time: '11:00', label: '11시' },
  { type: '평일', tag: '14', time: '14:00', label: '2시' },
  { type: '평일', tag: '15', time: '15:30', label: '3시반' },
  { type: '평일', tag: '18', time: '18:00', label: '6시' },
  { type: '주말', tag: '11', time: '11:00', label: '토요일 11시' },  // [v9.46] 주말 = 토요일만
  { type: '주말', tag: '14', time: '14:00', label: '토요일 2시' }
];

// [v9.95] 시간표 행 생성 — 순수 함수(tests/반편성.test.js 가 직접 로드해 반 수·정원·좌석 합계를 검증«했다».
//   ⚠삭제됨 08-19 e75fc7fc — 즉 **지금은 그 셋을 아무도 안 잰다.** 이 함수를 고칠 땐 손으로 대조한다).
//   시트 접근이 없으므로 "몇 반이 나오는가"를 배포 전에 기계로 확인할 수 있다.
function buildCoreSchedule_(rooms) {
  const n = Math.max(1, Math.min(ROOM_LETTERS.length, Math.round(Number(rooms) || CORE_ROOMS_DEFAULT)));
  const out = [];
  CORE_SLOTS.forEach(function (s) {
    for (let i = 0; i < n; i++) {
      out.push([s.type + s.tag + ROOM_LETTERS[i], s.type, s.time, CLASS_CAP_DEFAULT, s.label + ' ' + ROOM_LETTERS[i]]);
    }
  });
  return out;
}

function classNumOf(classStr) {
  // [v5.9] 이름 자유화 — "정규반3"뿐 아니라 "크루3", "홍대 3크루" 등 숫자가 포함된 어떤 이름도 OK
  //        (숫자 없는 반은 기존처럼 시간표 미등록 취급 → 달력일 방식 안전 폴백)
  const m = String(classStr).match(/(\d+)/);
  return m ? m[1] : '';
}
// [v9.68] 수업 시각 정규화 — schedule 시트의 시간 칸이 '시간 서식'이면 getValues()가 Date(1899-12-30 기준)를
//   돌려준다. 그대로 String()하면 "Sat Dec 30 1899 11:00:00 GMT+0700"이 되어 ①교실스크린에 그 문자열이 노출
//   ②':' split·정규식이 1899·30 같은 엉뚱한 숫자를 hour/min으로 잡아 미등원 알림·수업 전 메일 시각이 무너진다.
//   증상이 4곳에 흩어져 있으므로 소비처가 아니라 단일 소스(scheduleMap)에서 'HH:mm'으로 고정한다.
function hhmmOf_(v, tz) {
  if (v instanceof Date) return Utilities.formatDate(v, tz, 'HH:mm');
  const s = String(v == null ? '' : v).trim();
  const m = s.match(/^(\d{1,2})\s*[:시]\s*(\d{1,2})?/); // "9:00"·"9시"·"09:5" → 두 자리 정규화
  return m ? ('0' + m[1]).slice(-2) + ':' + ('0' + (m[2] || '0')).slice(-2) : s;
}
function scheduleMap(ss) { // [v8.3] 키 = 반명(정확 일치) · 번호 키는 '그 번호가 유일할 때만' 유지(구체계 하위호환)
  const sc = ss.getSheetByName('schedule');
  const map = {};
  const tzSc = ss.getSpreadsheetTimeZone();
  if (sc && sc.getLastRow() >= 2) {
    // [v9.95] 읽기 폭을 4·5열(정원·표시명)까지 넓힌다. 구 3열 시트(v9.45 이전)도 그대로 살아야 하므로
    //   폭은 실제 시트 기준으로 잡고, 없는 칸은 아래에서 기본값 폴백한다 — 마이그레이션 없이 양쪽이 동작한다.
    const w = Math.max(sc.getLastColumn(), 3);
    const rows = sc.getRange(2, 1, sc.getLastRow() - 1, w).getValues().filter(r => r[0]);
    const cnt = {};
    rows.forEach(r => { const n = classNumOf(r[0]); if (n) cnt[n] = (cnt[n] || 0) + 1; });
    rows.forEach(r => {
      const capRaw = Number(r[3]); // D열 '정원' — 구 v8.3의 이름 판정을 대체하는 단일 소스
      const e = {
        type: r[1], time: hhmmOf_(r[2], tzSc), name: String(r[0]),
        cap: (capRaw > 0 ? Math.round(capRaw) : CLASS_CAP_DEFAULT),
        disp: String(r[4] || '').trim() || String(r[0]) // E열 '표시명' — 비면 키를 그대로 쓴다(빈 이름 노출 차단)
      };
      map[String(r[0])] = e;
      const n = classNumOf(r[0]);
      if (n && cnt[n] === 1 && !map[n]) map[n] = e;
    });
  }
  return map;
}
function schedOf(map, cls) { return map[String(cls)] || map[classNumOf(cls)]; } // [v8.3] 반명 우선 조회
// [v9.46] 수업일 판정 단일 소스 — 주말반 = "토요일만"(2026-07-19 유호 확정). 일요일은 어느 반도 수업일이 아니다.
//   스트릭·개근·출석달력·수업일 환산·미등원·브리핑이 전부 이 함수를 따른다(일요일 끊김·오경보 원천 차단).
function classDowOk_(type, dow) { return String(type) === '주말' ? dow === 6 : (dow >= 1 && dow <= 5); }
function hasClassToday(ss, classStr, schMap) { // [v9.22] schMap 전달 시 재읽기 생략
  const s = schedOf(schMap || scheduleMap(ss), classStr); // [v8.3]
  if (!s) return false;
  return classDowOk_(s.type, new Date().getDay()); // [v9.46]
}

/* --- [v9.47] ⏱️ 실행 시간 예산 + 자동 이어하기 — Apps Script 6분 강제 종료 대책 ---
 * 긴 러너(preflightGlide·seedDemoData·clearDemoData)가 4.5분에서 우아하게 멈추고 1분 뒤 스스로 이어간다.
 * "중간에 죽음 → (시드는 clear까지 해서) 처음부터 반복"이 Glide 조립 시간낭비의 근본 원인이었다(2026-07-20 유호 보고).
 * 이어하기 트리거는 함수명당 1개만 유지 — 대상 3함수는 통합 트리거 10개와 이름이 겹치지 않아 name 기준 삭제가 안전하다. */
const RUN_BUDGET_MS = 270000; // 4.5분(6분 강제 종료 전 여유 90초)
function budgetOver_(t0) { return Date.now() - t0 > RUN_BUDGET_MS; }
function scheduleContinue_(fnName) {
  try {
    ScriptApp.getProjectTriggers().forEach(t => { if (t.getHandlerFunction() === fnName) ScriptApp.deleteTrigger(t); });
    ScriptApp.newTrigger(fnName).timeBased().after(60 * 1000).create();
  } catch (e) { Logger.log('이어하기 트리거 예약 실패(' + fnName + '): ' + e); }
}
function clearContinue_(fnName) {
  try { ScriptApp.getProjectTriggers().forEach(t => { if (t.getHandlerFunction() === fnName) ScriptApp.deleteTrigger(t); }); } catch (e) {}
}

/* ===================== [v9.120] 🧪 배치 리허설 모드 =====================
 * 문제: 개원 전에 배치·스위프를 검증해야 하는데, 돌리면 부작용이 밖으로 나간다 —
 *   학부모·강사에게 진짜 메일이 가고, Claude API 비용이 실제로 청구된다. 그래서 지금까지
 *   새 배치는 하룻밤을 기다리거나 코드 정적 검증으로 때웠다(실측: 결석 추적 v9.89가 그랬다).
 * 해법: 밖으로 나가는 것만 막고 로직은 그대로 돌린다. 관문이 이미 좁다 —
 *   메일 발송 46곳 중 43곳이 quotaOk를 거치고, AI 비용은 aiText_·callClaudeFeedback_ 둘뿐이다.
 *   그 6곳에만 게이트를 달면 나머지 코드는 한 줄도 안 바뀐다.
 * ⚠ 가장 큰 위험은 "켜둔 채 잊는 것"이다 — 리허설 중엔 진짜 알림도 안 나가므로, 밤이 오면
 *   그날 알림이 통째로 죽는다. 그래서 이중 안전장치를 둔다:
 *   ① TTL(기본 20분) 자동 만료  ② 야간 배치 진입 시 강제 해제 + 원장 통보.
 *   판정 실패 시에는 항상 '리허설 아님'(=정상 발송)으로 떨어진다 — 평상시가 압도적으로 많고,
 *   조용히 알림이 죽는 쪽이 조용히 메일 한 통 나가는 쪽보다 훨씬 비싸다. */
const REHEARSAL_UNTIL_KEY = '배치리허설_만료';
const REHEARSAL_LOG_KEY = '배치리허설_기록';
const REHEARSAL_TTL_MIN = 20;
const REHEARSAL_LOG_MAX = 6000;

function isRehearsal_() {
  try {
    // [v9.125] 실행 내 캐시 — quotaOk가 매 발송마다 이 함수를 지나므로 큰 루프(학부모 다이제스트 등)에서
    //   Properties 조회가 학생 수만큼 반복돼 6분 한도를 압박했다. 한 실행(수 분) 안에서 TTL(20분) 오차는 무해.
    if (isRehearsal_._c !== undefined && Date.now() - isRehearsal_._t < 30000) return isRehearsal_._c;
    const p = PropertiesService.getScriptProperties();
    const until = Number(p.getProperty(REHEARSAL_UNTIL_KEY) || 0);
    let on = false;
    if (until) {
      if (Date.now() > until) p.deleteProperty(REHEARSAL_UNTIL_KEY); // TTL 만료 = 자동 해제
      else on = true;
    }
    isRehearsal_._c = on; isRehearsal_._t = Date.now();
    return on;
  } catch (e) { return false; } // 판정 불가 → 정상 발송 쪽으로(게이트가 알림을 삼키지 않게)
}

// 차단된 것을 기록한다 — "무엇이 나갈 뻔했나"를 못 보면 리허설은 그냥 아무것도 안 한 것과 같다.
function rehearsalNote_(what) {
  try {
    const p = PropertiesService.getScriptProperties();
    const cur = String(p.getProperty(REHEARSAL_LOG_KEY) || '');
    if (cur.length > REHEARSAL_LOG_MAX) return; // 폭주 방지(Properties 용량 보호)
    p.setProperty(REHEARSAL_LOG_KEY, cur + '· ' + what + '\n');
  } catch (e) {}
}

// 야간 배치 진입점에서 호출 — 리허설이 켜진 채 밤이 오면 그날 알림이 통째로 죽는다.
function rehearsalForceOff_() {
  try {
    const p = PropertiesService.getScriptProperties();
    if (!p.getProperty(REHEARSAL_UNTIL_KEY)) return;
    p.deleteProperty(REHEARSAL_UNTIL_KEY);
    isRehearsal_._c = undefined; // [v9.125] 캐시 무효화 — 같은 실행에서 끈 직후 발송이 막히면 안 된다
    Logger.log('⚠ 리허설이 켜진 채 야간 배치 진입 — 강제 해제했다(그대로 두면 오늘 알림이 전부 죽는다)');
  } catch (e) {}
}

/* ── 리허설 조작부(메뉴에서 부른다) ─────────────────────────────────────
 * 배치 실행 항목은 반드시 리허설 가드를 통과해야 한다 — 실수로 눌렀을 때 아무 일도 없어야
 * 메뉴에 올릴 수 있다. 가드가 없으면 클릭 한 번이 학부모 메일 발송이 된다. */
function rehearsalStart() {
  const p = PropertiesService.getScriptProperties();
  p.setProperty(REHEARSAL_UNTIL_KEY, String(Date.now() + REHEARSAL_TTL_MIN * 60000));
  p.deleteProperty(REHEARSAL_LOG_KEY);
  isRehearsal_._c = undefined; // [v9.125] 실행 내 캐시 무효화 — 같은 실행에서 켠 직후를 캐시가 가리면 실발송이 샌다
  try {
    SpreadsheetApp.getUi().alert('🧪 리허설 시작 (' + REHEARSAL_TTL_MIN + '분)\n\n'
      + '지금부터 배치를 돌려도 메일이 나가지 않고 AI 비용도 들지 않습니다.\n'
      + '계산·시트 기록은 평소처럼 진행되니 결과를 그대로 확인하실 수 있습니다.\n\n'
      + '· 아래 「배치 실행」 항목들을 눌러 보세요\n'
      + '· 끝나면 「🧪 리허설 결과·종료」로 무엇이 나갈 뻔했는지 확인하세요\n\n'
      + '※ ' + REHEARSAL_TTL_MIN + '분 뒤 자동으로 꺼집니다(켜둔 채 잊어도 안전).');
  } catch (e) {}
}

function rehearsalReport() {
  const p = PropertiesService.getScriptProperties();
  const log = String(p.getProperty(REHEARSAL_LOG_KEY) || '');
  const on = isRehearsal_();
  p.deleteProperty(REHEARSAL_UNTIL_KEY);
  p.deleteProperty(REHEARSAL_LOG_KEY);
  const lines = log.split('\n').filter(String);
  try {
    SpreadsheetApp.getUi().alert('🧪 리허설 ' + (on ? '종료' : '종료(이미 만료됨)') + '\n\n'
      + (lines.length
          ? '차단된 외부 동작 ' + lines.length + '건 — 실제였다면 아래가 나갔습니다:\n\n'
            + lines.slice(0, 40).join('\n') + (lines.length > 40 ? '\n… 외 ' + (lines.length - 40) + '건' : '')
          : '차단된 외부 동작이 없습니다.\n\n배치를 안 돌렸거나, 보낼 대상이 없었다는 뜻입니다\n(개원 전이라 로스터가 비어 있으면 정상입니다).')
      + '\n\n이제 평소 상태로 돌아왔습니다.');
  } catch (e) {}
  return lines;
}

function rehearseAbsenceFollowup() { rehearseRun_('결석 복귀 판정', absenceFollowupNightly_); }
function rehearseAiFeedback() { rehearseRun_('AI 첨삭 배치', aiFeedbackBatch_); }

function rehearseRun_(label, fn) {
  const ui = (function () { try { return SpreadsheetApp.getUi(); } catch (e) { return null; } })();
  if (!isRehearsal_()) { // 리허설 밖에서는 절대 돌리지 않는다 — 이 한 줄이 메뉴 등재의 전제다
    if (ui) ui.alert('⛔ 먼저 「🧪 리허설 시작」을 눌러 주세요.\n\n'
      + '리허설 없이 ' + label + '을(를) 실행하면 강사·학부모에게 실제 메일이 발송되고\n'
      + 'AI 비용이 청구됩니다. 그래서 막았습니다.');
    return;
  }
  const t0 = Date.now();
  let err = '';
  try { fn(); } catch (e) { err = String(e); }
  const sec = ((Date.now() - t0) / 1000).toFixed(1);
  rehearsalNote_(label + ' 실행 ' + sec + '초' + (err ? ' · 오류: ' + err.slice(0, 120) : ''));
  if (ui) ui.alert('🧪 ' + label + ' 리허설 완료 (' + sec + '초)\n\n'
    + (err ? '⚠ 오류가 났습니다:\n' + err.slice(0, 300) + '\n\n이게 리허설의 목적입니다 — 실제 밤에 터졌으면 몰랐을 것입니다.'
           : '오류 없이 끝났습니다.')
    + '\n\n무엇이 나갈 뻔했는지는 「🧪 리허설 결과·종료」에서 봅니다.');
}

/* --- 메일 쿼터 가드 --- */
function quotaOk(needed) {
  // [v9.120] 리허설이면 여기서 전부 막힌다 — 발송 46곳 중 43곳이 이 관문을 지난다.
  if (isRehearsal_()) { rehearsalNote_('메일 ' + needed + '통 (차단)'); return false; }
  const q = MailApp.getRemainingDailyQuota();
  if (q >= needed + 3) return true;
  try {
    // [v9.25] 쿼터 경고 dedup — 쿼터가 바닥난 날 경고 메일이 매 호출마다 연쇄 발송돼 남은 쿼터를 마저 소진하는
    //         자기증폭 방지. 경고 분기 안에서만 ScriptProperties를 읽고 써서 1일 1회로 제한 (정상 경로엔 영향 없음).
    const props = PropertiesService.getScriptProperties();
    const today = Utilities.formatDate(new Date(), SpreadsheetApp.getActiveSpreadsheet().getSpreadsheetTimeZone(), 'yyyy-MM-dd');
    if (props.getProperty('쿼터경고일') !== today) {
      MailApp.sendEmail(ADMIN_EMAIL, '[SYNK] ⚠️ 메일 쿼터 부족',
        '오늘 남은 발송량 ' + q + '건, 필요 ' + needed + '건.\n' +
        '일부 알림이 발송되지 않았습니다. founder@synk.im(Workspace) 전환을 권장합니다.');
      props.setProperty('쿼터경고일', today);
    }
  } catch (e) {}
  return false;
}

